#!/usr/bin/env node
import { readFileSync } from "node:fs";
const args=process.argv.slice(2),mode=args.includes("--fake-mode")?args[args.indexOf("--fake-mode")+1]:"success";
if(args.includes("--version")){console.log("fake-goose 2.0.0");process.exit(0);}
